    const outHead = createAL("Outdoor Header", "HORIZONTAL", 8, 0, 2, null, null, 0);
    outHead.primaryAxisAlignItems = "SPACE_BETWEEN";
    tableCard.appendChild(outHead);
    outHead.layoutSizingHorizontal = "FILL";
    outHead.appendChild(makeText("AREA OUTDOOR", 11, "Bold", C.textMuted));
    outHead.appendChild(makeText("6 meja", 11, "Regular", C.textMuted));

