        const pill = createAL("Table " + code, "HORIZONTAL", 8, 14, 10, C.bg, C.border, 12);
        pill.primaryAxisAlignItems = "SPACE_BETWEEN";
        pill.counterAxisAlignItems = "CENTER";
        r.appendChild(pill);
        pill.layoutSizingHorizontal = "FILL";
